def balanced(s):
    stack = []
    i = 0
    n = len(s)
    while i < n:
        ch = s[i]
        if ch == '"' or ch == "'":
            quote = ch
            i += 1
            while i < n:
                if s[i] == '\\':
                    i += 2  # skip escaped char
                    continue
                if s[i] == quote:
                    i += 1
                    break
                i += 1
            else:
                # string not closed
                return False
            continue
        if ch in '([{':
            stack.append(ch)
        elif ch in ')]}':
            if not stack:
                return False
            top = stack.pop()
            if (top == '(' and ch != ')') or (top == '[' and ch != ']') or (top == '{' and ch != '}'):
                return False
        i += 1
    return not stack

# Required tests
tests = [
    ('([]{})', True),
    ('([)]', False),
    ('f("(")', True),
    ('"abc', False),
    ('', True),
]

all_pass = True
for s, expected in tests:
    res = balanced(s)
    if res != expected:
        print(f"FAIL: {repr(s)} expected {expected} got {res}")
        all_pass = False
if all_pass:
    print("ALL TESTS PASSED")
else:
    print("SOME TESTS FAILED")

